using NUnit.Framework;

[TestFixture]
public class CountEvenAndOddTests
{
    [Test]
    public void Counts_Even_And_Odd_Correctly()
    {
        var result = CountEvenAndOdd(new[] { 1, 2, 3, 4, 5 });

        Assert.That(result.even, Is.EqualTo(2));
        Assert.That(result.odd, Is.EqualTo(3));
    }

    private (int even, int odd) CountEvenAndOdd(int[] nums)
    {
        int even = 0;
        int odd = 0;

        foreach (var num in nums)
        {
            if (num % 2 == 0)
                even++;
            else
                odd++;
        }

        return (even, odd);
    }
}
